-- Canada deep-dive content translations (ES/DE/FR)

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'Sin mandato B2B — B2G a través de SAP Ariba', 'Esta página de análisis refleja la orientación disponible públicamente a partir de julio de 2026 y se proporciona con fines informativos generales, no como asesoramiento legal o fiscal. El panorama de facturación electrónica B2B de Canadá sigue siendo voluntario y no hay ningún mandato a la vista: confirme los desarrollos actuales directamente con la CRA o PSPC antes de tomar decisiones de infraestructura.', 'El gobierno federal de Canadá avanzó de forma decisiva en su propia contratación pública; todo lo demás ha permanecido en fase de estudio y señales durante varios años.', 'Fuera de la contratación federal, Canadá no prescribe ningún formato en absoluto: el requisito se refiere al contenido de la factura, no a su estructura.', 'No existe un mandato de facturación electrónica B2B en Canadá, y ninguno propuesto actualmente con un plazo fijo. La única obligación real y existente es B2G federal: los proveedores del Gobierno de Canadá deben facturar electrónicamente a través de SAP Ariba. Coexisten dos mundos completamente separados: un canal federal obligatorio y todo lo demás, sin regular.', 'Lo que significa "prepararse" aquí depende enteramente de en qué lado de la línea federal/todo lo demás se encuentre su negocio.', 'No existe un marco de sanciones por la falta de adopción B2B, porque no hay nada obligatorio que dejar de adoptar.' FROM countries WHERE name_en = 'Canada';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Kein B2B-Mandat — B2G über SAP Ariba', 'Diese Detailseite spiegelt öffentlich verfügbare Hinweise mit Stand Juli 2026 wider und dient allgemeinen Informationszwecken, nicht der Rechts- oder Steuerberatung. Kanadas B2B-E-Invoicing-Landschaft bleibt freiwillig, ein Mandat ist nicht in Sicht – bestätigen Sie aktuelle Entwicklungen direkt bei der CRA oder PSPC, bevor Sie Infrastrukturentscheidungen treffen.', 'Die kanadische Bundesregierung hat bei der eigenen Beschaffung entschieden gehandelt; alles darüber hinaus verharrt seit mehreren Jahren in der Phase von Studien und Signalen.', 'Außerhalb der Bundesbeschaffung schreibt Kanada überhaupt kein Format vor – die Anforderung betrifft den Rechnungsinhalt, nicht dessen Struktur.', 'Es gibt kein B2B-E-Invoicing-Mandat in Kanada, und derzeit ist keines mit festem Zeitplan vorgeschlagen. Die einzige tatsächliche, bestehende Verpflichtung ist B2G auf Bundesebene – Lieferanten der kanadischen Regierung müssen elektronisch über SAP Ariba fakturieren. Zwei völlig getrennte Welten existieren nebeneinander: ein verpflichtender Bundeskanal und ein unreguliertes Alles-andere.', 'Was "Vorbereitung" hier bedeutet, hängt vollständig davon ab, auf welcher Seite der Linie Bund/alles-andere Ihr Unternehmen steht.', 'Für Nichteinführung im B2B-Bereich existiert kein Sanktionsrahmen – weil es nichts Verpflichtendes gibt, dessen Nichteinführung bestraft werden könnte.' FROM countries WHERE name_en = 'Canada';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'Aucun mandat B2B — B2G via SAP Ariba', 'Cette page d''analyse reflète les orientations publiquement disponibles en date de juillet 2026 et est fournie à titre informatif général, non comme un avis juridique ou fiscal. Le paysage de la facturation électronique B2B au Canada demeure volontaire et aucun mandat n''est à l''horizon — confirmez les développements actuels directement auprès de l''ARC ou de SPAC avant de prendre des décisions d''infrastructure.', 'Le gouvernement fédéral du Canada a agi de façon décisive concernant ses propres approvisionnements; tout le reste est resté au stade de l''étude et des signaux depuis plusieurs années.', 'En dehors des approvisionnements fédéraux, le Canada ne prescrit aucun format — l''exigence porte sur le contenu de la facture, pas sur sa structure.', 'Il n''existe aucun mandat de facturation électronique B2B au Canada, et aucun n''est actuellement proposé avec un échéancier fixe. La seule obligation réelle et existante est le B2G fédéral — les fournisseurs du gouvernement du Canada doivent facturer électroniquement via SAP Ariba. Deux mondes entièrement séparés coexistent : un canal fédéral obligatoire, et tout le reste, non réglementé.', 'Ce que signifie « se préparer » ici dépend entièrement du côté de la ligne fédéral/tout le reste où se trouve votre entreprise.', 'Aucun cadre de sanctions n''existe pour la non-adoption B2B — car il n''y a rien d''obligatoire à ne pas adopter.' FROM countries WHERE name_en = 'Canada';

