INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Lo que realmente exige la CRA', '[["Formato", "Cualquier formato legible — papel, PDF o EDI"], ["Numeración", "Sin formato prescrito, pero debe ser única y rastreable en sus registros"]]', 'A la CRA no le importa si su factura es XML estructurado o un PDF escaneado; lo que importa es que incluya la información fiscal requerida y pueda rastrearse hasta sus libros durante una auditoría.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Los 9 campos requeridos', '[["Identidad", "Nombre comercial, número de GST/HST/Business Number, número de factura, fecha"], ["Transacción", "Descripción, importe"], ["Impuestos", "Desglose de impuestos, total"], ["Comercial", "Condiciones de pago"]]', 'Estos campos existen por dos razones: el cumplimiento de la CRA y permitir que su cliente reclame el crédito fiscal por insumos (ITC). Omitir específicamente el número de GST/HST puede bloquear por completo el ITC de su cliente.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Para proveedores del gobierno federal', '[["Estándares preferidos", "Formato Peppol BIS o UBL-XML"], ["Entrega", "A través de SAP Ariba, o cualquier proveedor de red Peppol certificado"]]', 'Este es el único lugar en Canadá donde realmente existen preferencias de formato estructurado por escrito; en cualquier otro lugar, lo que importa es el contenido, no la estructura.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Sin identificador Peppol canadiense', '[["Business Number de la CRA", "No puede usarse como identificador Peppol"], ["Solución alternativa", "Registrarse bajo GLN (esquema 0088) o DUNS (esquema 0060)"]]', 'Dado que Canadá no tiene una Autoridad Peppol nacional ni un esquema de identificadores propio, las empresas canadienses que desean conectividad Peppol usan un identificador internacional acordado bilateralmente con sus socios comerciales; no hay un paso de acreditación local que completar.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Variación fiscal provincial', '[["Ontario", "13% HST (federal + provincial combinado)"], ["Provincias atlánticas (NS, NB, PE, NL)", "15% HST"], ["Quebec", "5% GST + 9.975% QST, mostrados como líneas separadas (el QST se calcula solo sobre el subtotal)"], ["Alberta, TNO, Nunavut, Yukón", "Solo 5% GST — sin impuesto provincial sobre las ventas"], ["Otras provincias", "5% GST más PST administrado por separado, según la provincia"]]', 'Un pie de factura estático que asume una tasa impositiva única es un riesgo real para cualquier empresa que venda a través de fronteras provinciales: el tratamiento fiscal correcto depende de la provincia de suministro del cliente, no de la suya.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'file_format' AND dc.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Was die CRA tatsächlich verlangt', '[["Format", "Jedes lesbare Format — Papier, PDF oder EDI"], ["Nummerierung", "Kein vorgeschriebenes Format, muss aber eindeutig und in Ihren Unterlagen nachvollziehbar sein"]]', 'Der CRA ist es egal, ob Ihre Rechnung strukturiertes XML oder ein gescanntes PDF ist – wichtig ist, dass sie die erforderlichen Steuerinformationen enthält und bei einer Prüfung bis zu Ihren Büchern zurückverfolgt werden kann.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Die 9 Pflichtfelder', '[["Identität", "Firmenname, GST/HST-/Business Number, Rechnungsnummer, Datum"], ["Transaktion", "Beschreibung, Betrag"], ["Steuer", "Steueraufschlüsselung, Gesamtbetrag"], ["Kommerziell", "Zahlungsbedingungen"]]', 'Diese Felder existieren aus zwei Gründen: zur CRA-Konformität und um den Vorsteuerabzug (Input Tax Credit) Ihres Kunden zu ermöglichen. Fehlt insbesondere die GST/HST-Nummer, kann dies den ITC-Anspruch Ihres Kunden vollständig blockieren.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Für Lieferanten der Bundesregierung', '[["Bevorzugte Standards", "Peppol-BIS-Format oder UBL-XML"], ["Zustellung", "Über SAP Ariba oder jeden zertifizierten Peppol-Netzwerkanbieter"]]', 'Dies ist der einzige Ort in Kanada, an dem tatsächlich schriftlich festgelegte Präferenzen für strukturierte Formate existieren – überall sonst zählt der Inhalt, nicht die Struktur.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Keine kanadische Peppol-Kennung', '[["CRA Business Number", "Kann nicht als Peppol-ID verwendet werden"], ["Lösung", "Registrierung unter GLN (Schema 0088) oder DUNS (Schema 0060)"]]', 'Da Kanada weder eine nationale Peppol-Behörde noch ein eigenes Kennungsschema hat, verwenden kanadische Unternehmen, die Peppol-Konnektivität wünschen, eine international vereinbarte Kennung mit ihren Handelspartnern – ein lokaler Akkreditierungsschritt entfällt.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Provinzielle Steuervariation', '[["Ontario", "13% HST (Bundes- und Provinzsteuer kombiniert)"], ["Atlantikprovinzen (NS, NB, PE, NL)", "15% HST"], ["Québec", "5% GST + 9,975% QST, als separate Zeilen ausgewiesen (QST wird nur auf den Zwischenbetrag berechnet)"], ["Alberta, NWT, Nunavut, Yukon", "Nur 5% GST — keine provinzielle Umsatzsteuer"], ["Andere Provinzen", "5% GST plus separat verwaltete PST, je nach Provinz"]]', 'Eine statische Rechnungsfußzeile, die von einem einzigen Steuersatz ausgeht, ist ein reales Risiko für jedes Unternehmen, das über Provinzgrenzen hinweg verkauft – die korrekte steuerliche Behandlung hängt von der Lieferprovinz des Kunden ab, nicht von Ihrer eigenen.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'file_format' AND dc.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Ce que l''ARC exige réellement', '[["Format", "Tout format lisible — papier, PDF ou EDI"], ["Numérotation", "Aucun format prescrit, mais doit être unique et traçable dans vos registres"]]', 'L''ARC ne se soucie pas de savoir si votre facture est un XML structuré ou un PDF numérisé — ce qui compte, c''est qu''elle comporte les informations fiscales requises et puisse être retracée jusqu''à vos registres lors d''une vérification.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Les 9 champs requis', '[["Identité", "Nom commercial, numéro de TPS/TVH/numéro d''entreprise, numéro de facture, date"], ["Transaction", "Description, montant"], ["Taxe", "Ventilation des taxes, total"], ["Commercial", "Conditions de paiement"]]', 'Ces champs existent pour deux raisons : la conformité avec l''ARC et la possibilité pour votre client de réclamer son crédit de taxe sur les intrants (CTI). L''omission spécifique du numéro de TPS/TVH peut bloquer entièrement le CTI de votre client.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Pour les fournisseurs du gouvernement fédéral', '[["Normes privilégiées", "Format Peppol BIS ou UBL-XML"], ["Livraison", "Via SAP Ariba, ou tout fournisseur de réseau Peppol certifié"]]', 'C''est le seul endroit au Canada où des préférences de format structuré existent réellement par écrit — partout ailleurs, c''est le contenu qui compte, pas la structure.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Aucun identifiant Peppol canadien', '[["Numéro d''entreprise de l''ARC", "Ne peut pas être utilisé comme identifiant Peppol"], ["Solution de contournement", "S''enregistrer sous GLN (schéma 0088) ou DUNS (schéma 0060)"]]', 'Le Canada n''ayant ni autorité Peppol nationale ni système d''identifiants propre, les entreprises canadiennes souhaitant une connectivité Peppol utilisent un identifiant international convenu bilatéralement avec leurs partenaires commerciaux — aucune étape d''accréditation locale n''est nécessaire.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Variation fiscale provinciale', '[["Ontario", "13% HST (fédéral + provincial combiné)"], ["Provinces atlantiques (NS, NB, PE, NL)", "15% HST"], ["Québec", "5% TPS + 9,975% TVQ, indiquées sur des lignes distinctes (la TVQ est calculée uniquement sur le sous-total)"], ["Alberta, TNO, Nunavut, Yukon", "5% TPS seulement — aucune taxe de vente provinciale"], ["Autres provinces", "5% TPS plus une taxe de vente provinciale administrée séparément, selon la province"]]', 'Un pied de facture statique supposant un taux de taxe unique constitue un risque réel pour toute entreprise vendant à travers les frontières provinciales — le traitement fiscal correct dépend de la province de fourniture du client, pas de la vôtre.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'file_format' AND dc.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'B2G federal (obligatorio)', '[["Plataforma", "SAP Ariba, a través del portal de contratación CanadaBuys"], ["Autoridad", "Public Services and Procurement Canada (PSPC)"]]', 'Se trata de un requisito genuino, existente e inequívoco: si usted vende al Gobierno de Canadá, no hay ambigüedad sobre lo que se espera de usted.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'B2B doméstico (voluntario)', '[["Práctica común", "Correo electrónico con PDF, EDI en sectores comerciales establecidos"], ["Reporte en tiempo real", "Ninguno — el GST/HST funciona enteramente mediante declaraciones periódicas"]]', 'No existe una red nacional unificada para B2B doméstico: las empresas usan lo que su socio comercial acepte, desde papel hasta EDI empresarial.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'El uso real de Peppol en Canadá', '[["Escenario realista", "Transfronterizo — operaciones de la UE/Australia que facturan a filiales canadienses"], ["Acreditación local requerida", "Ninguna"]]', 'Sea realista al respecto: la adopción de Peppol en Canadá hoy en día está impulsada por grupos multinacionales que extienden infraestructura que ya operan en otros lugares, no por ningún impulso doméstico.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Fragmentación provincial y municipal', '[["Marco coordinado", "Ninguno"], ["Ejemplo de proyecto piloto", "Portal de facturación digital de la Junta Escolar de Vancouver"]]', 'Existen algunos proyectos piloto aislados de facturación digital provincial o municipal, pero no hay un marco coordinado interprovincial comparable a lo que ocurre a nivel federal.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Bundes-B2G (verpflichtend)', '[["Plattform", "SAP Ariba, über das Beschaffungsportal CanadaBuys"], ["Behörde", "Public Services and Procurement Canada (PSPC)"]]', 'Dies ist eine echte, bestehende, eindeutige Anforderung – wenn Sie an die kanadische Regierung verkaufen, besteht keine Unklarheit darüber, was von Ihnen erwartet wird.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Inländisches B2B (freiwillig)', '[["Gängige Praxis", "PDF per E-Mail, EDI in etablierten Handelssektoren"], ["Echtzeit-Meldung", "Keine — GST/HST läuft vollständig über periodische Steuererklärungen"]]', 'Es gibt kein einheitliches nationales Netzwerk für inländisches B2B – Unternehmen nutzen, was ihr Handelspartner akzeptiert, von Papier bis hin zu Unternehmens-EDI.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Peppols tatsächlicher Anwendungsfall in Kanada', '[["Realistisches Szenario", "Grenzüberschreitend — EU-/australische Aktivitäten, die kanadische Tochtergesellschaften fakturieren"], ["Lokale Akkreditierung erforderlich", "Keine"]]', 'Seien Sie sich darüber im Klaren: Die Peppol-Einführung in Kanada wird heute von multinationalen Konzernen vorangetrieben, die bereits andernorts betriebene Infrastruktur erweitern, nicht von einem inländischen Impuls.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Provinzielle und kommunale Fragmentierung', '[["Koordinierter Rahmen", "Keiner"], ["Beispielpilotprojekt", "Digitales Rechnungsportal des Vancouver School Board"]]', 'Es gibt eine Handvoll isolierter provinzieller oder kommunaler Pilotprojekte zur digitalen Rechnungsstellung, aber keinen koordinierten interprovinziellen Rahmen vergleichbar mit dem, was auf Bundesebene geschieht.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'B2G fédéral (obligatoire)', '[["Plateforme", "SAP Ariba, via le portail d''approvisionnement CanadaBuys"], ["Autorité", "Services publics et Approvisionnement Canada (SPAC)"]]', 'Il s''agit d''une exigence réelle, existante et sans ambiguïté — si vous vendez au gouvernement du Canada, il n''y a aucune ambiguïté sur ce qui est attendu de vous.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'B2B domestique (volontaire)', '[["Pratique courante", "PDF par courriel, EDI dans les secteurs commerciaux établis"], ["Déclaration en temps réel", "Aucune — la TPS/TVH fonctionne entièrement par déclarations périodiques"]]', 'Il n''existe aucun réseau national unifié pour le B2B domestique — les entreprises utilisent ce que leur partenaire commercial accepte, du papier à l''EDI d''entreprise.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'L''usage réel de Peppol au Canada', '[["Scénario réaliste", "Transfrontalier — des activités de l''UE/Australie facturant des filiales canadiennes"], ["Accréditation locale requise", "Aucune"]]', 'Soyez lucide à ce sujet : l''adoption de Peppol au Canada aujourd''hui est portée par des groupes multinationaux qui étendent une infrastructure déjà exploitée ailleurs, et non par un élan domestique.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Fragmentation provinciale et municipale', '[["Cadre coordonné", "Aucun"], ["Exemple de projet pilote", "Portail de facturation numérique du Vancouver School Board"]]', 'Quelques projets pilotes isolés de facturation numérique provinciale ou municipale existent, mais aucun cadre interprovincial coordonné comparable à ce qui se passe au niveau fédéral.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Si usted es proveedor del gobierno federal, regístrese en SAP Ariba a través de CanadaBuys', 'Este es el único paso genuinamente obligatorio en todo el panorama canadiense: confirme que su registro e integración estén actualizados.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Canada' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Para todos los demás, confirme que sus facturas incluyan los 9 campos requeridos por la CRA', 'Nombre comercial, número de GST/HST/Business Number, fecha, número de factura, descripción, importe, desglose fiscal provincial correcto, total y condiciones de pago.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Canada' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Ajuste correctamente su lógica fiscal provincial', 'Confirme que su sistema de facturación aplique el tratamiento fiscal correcto según la provincia de suministro del cliente: el HST de Ontario, las líneas separadas de GST/QST de Quebec, o la regla de solo GST de Alberta requieren lógicas diferentes.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Canada' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Elija un identificador Peppol solo si realmente necesita conectividad transfronteriza', 'Si una contraparte europea o australiana solicita conectividad Peppol, regístrese con un identificador GLN o DUNS a través de cualquier Access Point estándar; no hay ningún requisito doméstico que impulse esta decisión.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Canada' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Establezca una conservación de registros de 6 años', 'Conserve las facturas y la documentación de respaldo durante al menos seis años desde el final del año fiscal correspondiente; la CRA puede solicitarlas mucho después durante una auditoría o revisión.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Canada' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Siga el ciclo del plan regulatorio de la CRA, no una fecha límite fija', 'No hay una cuenta regresiva en torno a la cual planificar; en su lugar, revise periódicamente los planes regulatorios publicados por la CRA en busca de cualquier señal futura de que un mandato nacional de facturación electrónica pase de estudio a propuesta.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Canada' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wenn Sie die Bundesregierung beliefern, registrieren Sie sich über CanadaBuys in SAP Ariba', 'Dies ist der einzig wirklich verpflichtende Schritt in der gesamten kanadischen Landschaft – bestätigen Sie, dass Ihre Registrierung und Integration aktuell sind.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Canada' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Für alle anderen: Bestätigen Sie, dass Ihre Rechnungen alle 9 von der CRA geforderten Felder enthalten', 'Firmenname, GST/HST-/Business Number, Datum, Rechnungsnummer, Beschreibung, Betrag, korrekte provinzielle Steueraufschlüsselung, Gesamtbetrag und Zahlungsbedingungen.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Canada' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bringen Sie Ihre provinzielle Steuerlogik in Ordnung', 'Stellen Sie sicher, dass Ihr Rechnungssystem die korrekte steuerliche Behandlung basierend auf der Lieferprovinz des Kunden anwendet – Ontarios HST, Québecs getrennte GST/QST-Zeilen oder Albertas Nur-GST-Regel erfordern jeweils unterschiedliche Logik.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Canada' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wählen Sie eine Peppol-Kennung nur, wenn Sie tatsächlich grenzüberschreitende Konnektivität benötigen', 'Wenn ein europäischer oder australischer Geschäftspartner Peppol-Konnektivität anfordert, registrieren Sie sich über einen beliebigen Standard-Access-Point mit einer GLN- oder DUNS-Kennung – es gibt keine inländische Anforderung, die diese Entscheidung vorantreibt.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Canada' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Richten Sie eine 6-jährige Aufbewahrungsfrist ein', 'Bewahren Sie Rechnungen und Belege mindestens sechs Jahre ab dem Ende des betreffenden Steuerjahres auf – die CRA kann sie im Rahmen einer Prüfung oder Überprüfung auch noch lange danach anfordern.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Canada' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Verfolgen Sie den Regulierungsplan-Zyklus der CRA statt einer festen Frist', 'Es gibt keinen Countdown, an dem man sich orientieren könnte – prüfen Sie stattdessen regelmäßig die veröffentlichten Regulierungspläne der CRA auf jedes zukünftige Signal, dass ein inländisches E-Invoicing-Mandat vom Studium zum Vorschlag übergeht.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Canada' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Si vous approvisionnez le gouvernement fédéral, inscrivez-vous sur SAP Ariba via CanadaBuys', 'C''est la seule étape véritablement obligatoire dans tout le paysage canadien — confirmez que votre inscription et votre intégration sont à jour.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Canada' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Pour tous les autres, confirmez que vos factures comportent les 9 champs requis par l''ARC', 'Nom commercial, numéro de TPS/TVH/numéro d''entreprise, date, numéro de facture, description, montant, ventilation fiscale provinciale correcte, total et conditions de paiement.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Canada' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Mettez au point votre logique fiscale provinciale', 'Confirmez que votre système de facturation applique le traitement fiscal correct selon la province de fourniture du client — la HST de l''Ontario, les lignes distinctes TPS/TVQ du Québec, ou la règle TPS seulement de l''Alberta nécessitent chacune une logique différente.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Canada' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Choisissez un identifiant Peppol seulement si vous avez réellement besoin d''une connectivité transfrontalière', 'Si une contrepartie européenne ou australienne demande une connectivité Peppol, inscrivez-vous avec un identifiant GLN ou DUNS via n''importe quel Access Point standard — aucune exigence domestique ne motive cette décision.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Canada' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Mettez en place une conservation des registres de 6 ans', 'Conservez les factures et documents justificatifs pendant au moins six ans à compter de la fin de l''année fiscale concernée — l''ARC peut les demander bien après coup lors d''une vérification ou d''un examen.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Canada' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Surveillez le cycle du plan de réglementation de l''ARC, pas une échéance fixe', 'Il n''y a pas de compte à rebours autour duquel planifier — vérifiez plutôt périodiquement les plans de réglementation publiés par l''ARC pour tout signal futur qu''un mandat national de facturation électronique passe du stade de l''étude à celui de la proposition.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Canada' AND ds.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '💰 Sin sanciones, sin ley de formato', NULL, NULL, 'Los impuestos provinciales sobre las ventas y las normas de GST/HST no especifican en absoluto el formato de la factura: no existen sanciones canadienses vinculadas al uso de facturas en papel frente a digitales bajo la legislación de impuestos sobre las ventas.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🤔 Las propias partes interesadas de la CRA señalaron el problema del huevo y la gallina', NULL, NULL, 'El estudio de 2021 sacó a la luz una preocupación empresarial genuinamente honesta: adoptar la facturación electrónica parece inútil si las empresas con las que trabaja no lo han hecho, una ilustración real de por qué los sistemas voluntarios dependientes de efectos de red pueden estancarse sin un impulso regulatorio.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '📈 La adopción está ocurriendo de todos modos, gradualmente', NULL, NULL, 'Los datos de pagos a pequeñas empresas sugieren que los períodos promedio de pago tardío en Canadá han ido mejorando trimestre tras trimestre, atribuido en parte a la adopción gradual de la facturación electrónica: el cambio está ocurriendo de forma orgánica, simplemente sin un mandato que lo obligue.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🌍 La presión, cuando llegue, será externa', NULL, NULL, 'A medida que los mandatos de Europa se implementen gradualmente entre 2026 y 2030 y el requisito de Singapur alcance la cobertura completa de contribuyentes registrados en el GST para 2031, los exportadores canadienses que comercian con esos mercados sentirán el impulso hacia la infraestructura de facturación electrónica mucho antes de que cualquier ley nacional lo exija.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'penalties_related' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '💰 Keine Sanktionen, kein Formatgesetz', NULL, NULL, 'Provinzielle Verkaufssteuern und GST/HST-Regeln legen überhaupt kein Rechnungsformat fest – es gibt keine kanadischen Sanktionen, die an die Verwendung von Papier- statt digitalen Rechnungen nach dem Verkaufssteuerrecht geknüpft sind.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🤔 CRAs eigene Stakeholder wiesen auf das Henne-Ei-Problem hin', NULL, NULL, 'Die Studie von 2021 brachte eine wirklich ehrliche Geschäftssorge zutage: Die Einführung von E-Invoicing erscheint sinnlos, wenn die Unternehmen, mit denen Sie zusammenarbeiten, dies nicht getan haben – eine reale Veranschaulichung, warum freiwillige, netzwerkeffektabhängige Systeme ohne regulatorischen Druck ins Stocken geraten können.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '📈 Die Einführung geschieht trotzdem, schrittweise', NULL, NULL, 'Zahlungsdaten von Kleinunternehmen deuten darauf hin, dass sich die durchschnittlichen Zahlungsverzugszeiten in Kanada von Quartal zu Quartal verbessert haben, was teilweise auf die schrittweise Einführung von E-Invoicing zurückgeführt wird – der Wandel vollzieht sich organisch, nur eben ohne ein erzwingendes Mandat.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🌍 Der Druck, wenn er kommt, wird von außen kommen', NULL, NULL, 'Während Europas Mandate bis 2026–2030 schrittweise in Kraft treten und Singapurs Anforderung bis 2031 die vollständige Abdeckung GST-registrierter Unternehmen erreicht, werden kanadische Exporteure, die mit diesen Märkten Handel treiben, den Zug hin zu einer E-Invoicing-Infrastruktur lange spüren, bevor ein inländisches Gesetz dies verlangt.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'penalties_related' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '💰 Aucune sanction, aucune loi sur le format', NULL, NULL, 'Les taxes de vente provinciales et les règles de TPS/TVH ne précisent pas du tout le format de facture — il n''existe aucune sanction canadienne liée à l''utilisation de factures papier plutôt que numériques en vertu de la législation sur les taxes de vente.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🤔 Les propres parties prenantes de l''ARC ont signalé le problème de l''œuf et de la poule', NULL, NULL, 'L''étude de 2021 a mis au jour une préoccupation commerciale véritablement sincère : adopter la facturation électronique semble inutile si les entreprises avec lesquelles vous travaillez ne l''ont pas fait — une illustration réelle de la raison pour laquelle les systèmes volontaires dépendants des effets de réseau peuvent stagner sans impulsion réglementaire.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '📈 L''adoption progresse tout de même, graduellement', NULL, NULL, 'Les données de paiement des petites entreprises suggèrent que les délais moyens de paiement tardif au Canada se sont améliorés trimestre après trimestre, en partie attribué à l''adoption progressive de la facturation électronique — le changement se produit de manière organique, simplement sans mandat pour l''imposer.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🌍 La pression, lorsqu''elle viendra, sera externe', NULL, NULL, 'Alors que les mandats européens entrent progressivement en vigueur entre 2026 et 2030 et que l''exigence de Singapour atteint la pleine couverture des assujettis à la TPS d''ici 2031, les exportateurs canadiens commerçant avec ces marchés ressentiront l''attrait vers une infrastructure de facturation électronique bien avant qu''une loi domestique ne l''exige.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Canada' AND dc.section = 'penalties_related' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'es', 'Canada.ca — Contratación electrónica (PSPC)' FROM deep_dive_portals dp JOIN countries co ON co.id = dp.country_id WHERE co.name_en = 'Canada' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'es', 'Agencia de Ingresos de Canadá' FROM deep_dive_portals dp JOIN countries co ON co.id = dp.country_id WHERE co.name_en = 'Canada' AND dp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'de', 'Canada.ca — Elektronische Beschaffung (PSPC)' FROM deep_dive_portals dp JOIN countries co ON co.id = dp.country_id WHERE co.name_en = 'Canada' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'de', 'Kanadische Steuerbehörde (CRA)' FROM deep_dive_portals dp JOIN countries co ON co.id = dp.country_id WHERE co.name_en = 'Canada' AND dp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'fr', 'Canada.ca — Approvisionnement électronique (SPAC)' FROM deep_dive_portals dp JOIN countries co ON co.id = dp.country_id WHERE co.name_en = 'Canada' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'fr', 'Agence du revenu du Canada' FROM deep_dive_portals dp JOIN countries co ON co.id = dp.country_id WHERE co.name_en = 'Canada' AND dp.sort_order = 1;
